package api

import (
	"encoding/json"
	"fmt"
	"log/slog"
	"net/http"
	"time"

	"github.com/prometheus/client_golang/prometheus/promhttp"

	"gitlab.opencode.de/open-code/badgebackend/badge-api/pkg/api/handler"
	"gitlab.opencode.de/open-code/badgebackend/badge-api/pkg/api/middleware"
	"gitlab.opencode.de/open-code/badgebackend/badge-api/pkg/config"
)

func infoHandler(res http.ResponseWriter, req *http.Request) {
	// just return the current runtime configuration
	res.Header().Set("Content-Type", "application/json")
	res.WriteHeader(http.StatusOK)

	bytes, err := json.Marshal(config.RuntimeConfig)
	if err != nil {
		slog.Error("failed to marshal runtime config", "err", err)
		http.Error(res, "failed to marshal runtime config", http.StatusInternalServerError)
		return
	}

	_, err = res.Write(bytes)
	if err != nil {
		slog.Error("failed to write response", "err", err)
		http.Error(res, "failed to write response", http.StatusInternalServerError)
		return
	}
}

// Start a new api server
// this call will block forever
func Start(port string) error {

	repositoryHandler := handler.NewRepositoryHandler()

	mux := &http.ServeMux{}

	mux.HandleFunc(fmt.Sprintf("GET %s/info", config.API_PATH_PREFIX), infoHandler)
	mux.HandleFunc(fmt.Sprintf("GET %s/repositories/{repositoryURL}/sarif", config.API_PATH_PREFIX), repositoryHandler.GetRepositoryReport)
	mux.HandleFunc(fmt.Sprintf("GET %s/repositories/{repositoryURL}/badges/{badgeID}", config.API_PATH_PREFIX), repositoryHandler.GetRepositoryBadgeFile)
	mux.HandleFunc(fmt.Sprintf("GET %s/repositories/{repositoryURL}/badges/{badgeID}/sarif", config.API_PATH_PREFIX), repositoryHandler.GetRepositoryBadgeReport)

	mux.HandleFunc(fmt.Sprintf("GET %s/svg/{svgKey}", config.API_PATH_PREFIX), repositoryHandler.GetSvg)

	// instrument the application using prometheus
	mux.Handle("/metrics", promhttp.Handler())

	serverHandler := middleware.LockConfigRefreshMiddleware(middleware.SlogMiddleware(middleware.CorsMiddleware(mux)))

	slog.Info("starting server", "port", port)
	server := &http.Server{
		Addr:              fmt.Sprintf(":%s", port),
		Handler:           serverHandler,
		ReadHeaderTimeout: 3 * time.Second,
	}

	if err := server.ListenAndServe(); err != nil {
		slog.Error("failed to start server", "err", err)
		return err
	}
	return nil
}
